package designdb

import (
	"fmt"

	"aocrop/services/internal/usmap"
)

// Patch inserts a property into a struct of the mappings file, for a property
// the database has (and the client executable) that the mappings file lacks:
// the mappings describe a build, the database was generated by a later one.
type Patch struct {
	Struct string     // the struct to change
	After  string     // the property the new one goes after
	Prop   usmap.Prop // the property to insert
	Why    string     // the evidence
}

// String names the patch: "AbilityHitRecordBase.bMayCorrupt after ApplicableLifeStates".
func (p Patch) String() string {
	return p.Struct + "." + p.Prop.Name + " after " + p.After
}

// PatchStatus says what became of a patch.
type PatchStatus uint8

const (
	PatchApplied  PatchStatus = iota // the property was inserted
	PatchPresent                     // the mappings already have the property (a newer usmap)
	PatchNoStruct                    // the mappings have no such struct
	PatchNoAnchor                    // the struct has no property to insert the new one after
)

func (s PatchStatus) String() string {
	switch s {
	case PatchApplied:
		return "applied"
	case PatchPresent:
		return "already present"
	case PatchNoStruct:
		return "struct missing"
	case PatchNoAnchor:
		return "anchor missing"
	}
	return fmt.Sprintf("PatchStatus(%d)", uint8(s))
}

// PatchResult is a patch and what became of it.
type PatchResult struct {
	Patch  Patch
	Status PatchStatus
}

// (Cyb : C | O | A)

// patches are the changes to the mappings file the walk needs. The database
// (CacheDB.dbc, generated 2026-01-20) is newer than the old usmap
// (5.6.0-434126 AOC_FIXED) and, in these structs, agrees with the Steam client
// (2026-01-29, from which tools/ghidra/usmapgen.py writes a usmap): the old
// usmap lacks four properties the rows hold, and without them a table's rows
// do not end where the directory says, or end there by coincidence and read
// the wrong thing. Each patch is checked by the exact end-of-table test and by
// the values, and is "already present" in the generated usmap, which needs
// no patch.
//
//   - AbilityHitRecordBase.bMayCorrupt (Bool), between ApplicableLifeStates and
//     DefaultFallbackTargetType: the executable's FStructParams for AbilityHit, at
//     0x14d2e0e80, list 89 own properties against the old usmap's 88. In the file
//     it is one byte in each of the 3,608 AbilityHit rows, and with it the table's
//     rows end exactly on its last byte, 0x3C8C0F.
//   - PopulationAreaCircle.MaxNumSpawns (Int), after Weight: the 608 PopulationArea
//     rows end exactly with it and not without.
//   - PopulationInteractZone.Rotation (a Rotator), after Extents: the old usmap
//     lists ZoneFGuid and OwningVolumeGuid instead, 24 bytes that the executable
//     marks Transient (not stored, Facts.NotStored), so its walk of the 62
//     PopulationInteractVolume rows ended where it should by coincidence and read
//     a location as a Guid; with the facts and Rotation the rows read a location,
//     an extent and a rotation (PV_0026_MinotaurBlocker: (-561823, 598365, 15492),
//     1000, none).
//   - WindowDetails.Banner (a SoftObjectPath), after IconImage: the same
//     coincidence, 4 bytes for 4, with IconImage (Transient now) in the old usmap;
//     the 91 Windows rows hold the Banner path there.
var patches = []Patch{
	{
		Struct: "AbilityHitRecordBase",
		After:  "ApplicableLifeStates",
		Prop:   usmap.Prop{ArrayDim: 1, Name: "bMayCorrupt", Type: &usmap.Type{Kind: usmap.KindBool}},
		Why:    "the exe's FStructParams for AbilityHit (0x14d2e0e80) have 89 own properties, the old usmap 88",
	},
	{
		Struct: "PopulationAreaCircle",
		After:  "Weight",
		Prop:   usmap.Prop{ArrayDim: 1, Name: "MaxNumSpawns", Type: &usmap.Type{Kind: usmap.KindInt}},
		Why:    "the exe's PopulationAreaCircle has it; the 608 PopulationArea rows end exactly with it",
	},
	{
		Struct: "PopulationInteractZone",
		After:  "Extents",
		Prop:   usmap.Prop{ArrayDim: 1, Name: "Rotation", Type: &usmap.Type{Kind: usmap.KindStruct, Struct: "Rotator"}},
		Why:    "the exe's PopulationInteractZone has it where the old usmap lists 24 Transient bytes; the rows read a location, extent and rotation",
	},
	{
		Struct: "WindowDetails",
		After:  "IconImage",
		Prop:   usmap.Prop{ArrayDim: 1, Name: "Banner", Type: &usmap.Type{Kind: usmap.KindStruct, Struct: "SoftObjectPath"}},
		Why:    "the exe's WindowDetails has it where the old usmap lists IconImage, which is Transient; the 91 Windows rows hold the path",
	},
}

// Patches returns the changes to the mappings file the walk needs (a copy:
// the list is fixed). Decoder applies them.
func Patches() []Patch { return append([]Patch(nil), patches...) }

// applyPatches returns m with the patches applied (m itself is not changed)
// and what became of each patch.
func applyPatches(m *usmap.Map, patches []Patch) (*usmap.Map, []PatchResult) {
	results := make([]PatchResult, 0, len(patches))
	var changed map[string]*usmap.Schema
	for _, p := range patches {
		sc := m.Schema(p.Struct)
		if cp := changed[p.Struct]; cp != nil {
			sc = cp
		}
		if sc == nil {
			results = append(results, PatchResult{p, PatchNoStruct})
			continue
		}
		at, has := -1, false
		for i, pr := range sc.Props {
			if pr.Name == p.After {
				at = i
			}
			if pr.Name == p.Prop.Name {
				has = true
			}
		}
		if has {
			results = append(results, PatchResult{p, PatchPresent})
			continue
		}
		if at < 0 {
			results = append(results, PatchResult{p, PatchNoAnchor})
			continue
		}
		props := make([]usmap.Prop, 0, len(sc.Props)+1)
		props = append(props, sc.Props[:at+1]...)
		ins := p.Prop
		ins.Index = sc.Props[at].Index + 1
		props = append(props, ins)
		props = append(props, sc.Props[at+1:]...)
		cp := &usmap.Schema{Name: sc.Name, Super: sc.Super, PropCount: sc.PropCount + 1, Props: props}
		if changed == nil {
			changed = map[string]*usmap.Schema{}
		}
		changed[p.Struct] = cp
		results = append(results, PatchResult{p, PatchApplied})
	}
	if changed == nil {
		return m, results
	}
	schemas := make([]*usmap.Schema, len(m.Schemas))
	for i, sc := range m.Schemas {
		if cp := changed[sc.Name]; cp != nil {
			sc = cp
		}
		schemas[i] = sc
	}
	return usmap.New(m.Enums, schemas), results
}
